-- 226 (17/11/2026, lô 55): « DELF B1 · Đề 5 », phần ĐỌC viết lại khó hơn (văn bản dài hơn, câu hỏi về hàm ý).
-- Sinh bởi scripts/nhap/lo55_kho.mjs --cap B1 --de 5. Sửa thẳng, giữ id bài và id câu (cập nhật theo ord). Chạy lại an toàn.
-- lo22mvemxyoo02c
update public.exercises set consigne = '<p>Vous cherchez une activité pour vous détendre. Lisez les annonces et répondez aux questions.</p>', reading_text = '<p><strong>A. Yoga au parc</strong> : le dimanche à 10 h, en plein air, tous niveaux. Gratuit et sans inscription : il suffit d''apporter son tapis. En cas de pluie, la séance est annulée et un message est publié le matin même sur la page de l''association.</p><p><strong>B. Groupe de parole étudiant</strong> : le jeudi à 19 h, à la maison des étudiants. Un temps d''échange animé par une psychologue, pour parler du stress, de la solitude ou de la vie loin de sa famille. Huit personnes au maximum. Gratuit, mais inscription obligatoire ; ce que chacun dit reste confidentiel.</p><p><strong>C. Chorale du quartier</strong> : le lundi à 20 h, salle des fêtes. Aucun niveau demandé, aucune connaissance de la musique nécessaire : on apprend les chants à l''oreille. 40 € l''année. Deux concerts sont donnés chaque année, mais personne n''est obligé d''y participer. Les répétitions se terminent toujours par un moment convivial autour d''une boisson chaude.</p><p><strong>D. Jardin partagé</strong> : le samedi matin, rue des Lilas. Venez planter, arroser et récolter avec vos voisins. Aucune expérience du jardinage n''est nécessaire : les plus anciens conseillent les nouveaux. Outils prêtés, gants à apporter. Les légumes sont partagés entre les participants. Adhésion libre : chacun donne ce qu''il veut.</p><p><strong>E. Méditation en ligne</strong> : une application pour apprendre à respirer et à se concentrer, dix minutes par jour, où et quand vous voulez. 5 € par mois, gratuite pendant deux semaines. Déconseillée aux personnes qui souffrent de troubles graves : parlez-en d''abord à un médecin.</p>' where id = 'lo22mvemxyoo02c';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'qcm', 'Vous voulez parler de vos difficultés avec un professionnel, en petit groupe. Vous choisissez…', '{"options":["E","B","C"]}'::jsonb, '{"answer":1}'::jsonb, 'B: « animé par une psychologue » và « Huit personnes au maximum ».'),
  (2, 'qcm', 'Vous aimez chanter, mais vous ne savez pas lire la musique. Vous choisissez…', '{"options":["C","A","D"]}'::jsonb, '{"answer":0}'::jsonb, 'C: « aucune connaissance de la musique nécessaire : on apprend les chants à l''oreille ».'),
  (3, 'qcm', 'Vous avez peu de temps, vous voulez pratiquer chez vous et ne rien payer au début. Vous choisissez…', '{"options":["A","E","B"]}'::jsonb, '{"answer":1}'::jsonb, 'E: « dix minutes par jour, où et quand vous voulez » và « gratuite pendant deux semaines ». A miễn phí nhưng ở ngoài trời.'),
  (4, 'qcm', 'Quelle activité permet de repartir avec de la nourriture ?', '{"options":["A","D","C"]}'::jsonb, '{"answer":1}'::jsonb, 'D: « Les légumes sont partagés entre les participants ».'),
  (5, 'qcm', 'Pour le yoga, comment sait-on qu''une séance est annulée ?', '{"options":["sur la page de l''association","par un appel de l''animateur","par un SMS envoyé la veille au soir"]}'::jsonb, '{"answer":0}'::jsonb, '« un message est publié le matin même sur la page de l''association ».')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo22mvemxyoo02c' and q.ord = v.ord;

-- lo22mvemxyoo02d
update public.exercises set consigne = '<p>Lisez l''article puis répondez aux questions.</p>', reading_text = '<p><strong>Santé mentale des jeunes : une grande cause qui doit encore faire ses preuves</strong></p><p>En 2025, la santé mentale avait été déclarée « grande cause nationale » en France. Fin novembre 2025, le gouvernement a annoncé qu''elle le resterait en 2026, en promettant cette fois des actions plus concrètes. Cette décision répondait notamment à une demande des hôpitaux publics, qui souhaitaient que l''effort porte en priorité sur les jeunes. Reconduire un label, cependant, ne coûte rien ; c''est à ce qui suit qu''on juge une politique.</p><p>Les chiffres expliquent l''inquiétude des soignants. Selon une étude de Santé publique France menée auprès de 17 000 jeunes, environ un tiers des 11 à 24 ans présente des signes de détresse anxieuse ou dépressive, de modérée à sévère. Les hôpitaux constatent par ailleurs que les jeunes de 5 à 19 ans ont été beaucoup plus nombreux que prévu à être hospitalisés pour des troubles psychiatriques en 2024. Derrière ces pourcentages, il y a des familles qui attendent, parfois longtemps, une réponse qui ne vient pas.</p><p>Car l''offre de soins ne suit pas. Les services de psychiatrie sont saturés, de nombreux postes ne sont pas pourvus, et beaucoup de patients disent avoir déjà renoncé à un rendez-vous faute de place. Ce renoncement est sans doute le plus préoccupant : un jeune qui a trouvé le courage de demander de l''aide et qui se heurte à une porte fermée risque de ne pas frapper une deuxième fois. Chaque mois d''attente compte, surtout à un âge où les difficultés peuvent vite s''aggraver. Des députés ont d''ailleurs regretté que les mesures avancent trop lentement.</p><p>Quelques changements concrets arrivent malgré tout. Depuis le 1er octobre 2026, les patients du dispositif « Mon soutien psy » n''ont plus à avancer les frais chez le psychologue, ce qui supprime un obstacle financier réel pour les plus modestes. Les étudiants, eux, peuvent toujours bénéficier de séances gratuites. Pour les spécialistes, ces aides sont utiles, mais elles ne remplacent pas un vrai plan pour former et recruter des soignants. Faciliter l''accès à un psychologue n''a guère de sens, rappellent-ils, si les professionnels manquent pour recevoir ceux qui en ont besoin. Autrement dit, ouvrir la porte ne suffit pas ; encore faut-il que quelqu''un attende derrière. C''est sur ce point que les prochains mois diront si la grande cause en était vraiment une.</p><p><p><small><em>Texte rédigé par FRACILE à partir de : Fédération hospitalière de France, lettre ouverte, 27 novembre 2025 (fhf.fr) ; CIDJ, « Ce qui change en octobre 2026 », 1er octobre 2026 (cidj.com) ; Pourquoi Docteur, « Santé mentale, grande cause nationale 2026 » (pourquoidocteur.fr).</em></small></p></p>' where id = 'lo22mvemxyoo02d';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'qcm', 'Selon l''auteur, reconduire la « grande cause nationale »…', '{"options":["a coûté très cher à l''État.","ne suffit pas à juger une politique.","a été critiqué par les hôpitaux publics."]}'::jsonb, '{"answer":1}'::jsonb, '« Reconduire un label, cependant, ne coûte rien ; c''est à ce qui suit qu''on juge une politique ».'),
  (2, 'qcm', 'Qu''avaient demandé les hôpitaux publics ?', '{"options":["que la grande cause soit abandonnée","que les jeunes soient la priorité","que les étudiants paient moins cher"]}'::jsonb, '{"answer":1}'::jsonb, '« qui souhaitaient que l''effort porte en priorité sur les jeunes ».'),
  (3, 'qcm', 'D''après l''étude de Santé publique France,…', '{"options":["la moitié des jeunes a déjà été hospitalisée.","17 000 jeunes souffrent d''une dépression grave et durable.","environ un jeune sur trois montre des signes de détresse."]}'::jsonb, '{"answer":2}'::jsonb, '« environ un tiers des 11 à 24 ans présente des signes de détresse anxieuse ou dépressive ». 17 000 là số người được khảo sát.'),
  (4, 'vf', 'En 2024, les jeunes hospitalisés pour des troubles psychiatriques ont été moins nombreux que prévu.', '{}'::jsonb, '{"answer":1,"justification":"ont été beaucoup plus nombreux que prévu à être hospitalisés"}'::jsonb, null),
  (5, 'qcm', 'Pourquoi l''auteur juge-t-il le renoncement aux soins particulièrement grave ?', '{"options":["Un jeune refusé une fois risque de ne plus demander d''aide.","Les familles portent plainte contre les services.","Les rendez-vous non honorés font perdre beaucoup d''argent aux hôpitaux."]}'::jsonb, '{"answer":0}'::jsonb, '« un jeune qui a trouvé le courage de demander de l''aide et qui se heurte à une porte fermée risque de ne pas frapper une deuxième fois ».'),
  (6, 'qcm', 'Qu''ont reproché des députés ?', '{"options":["le manque de chiffres fiables","le coût des séances gratuites","la lenteur des mesures"]}'::jsonb, '{"answer":2}'::jsonb, '« Des députés ont d''ailleurs regretté que les mesures avancent trop lentement ».'),
  (7, 'vf', 'Depuis le 1er octobre 2026, les patients de « Mon soutien psy » ne paient plus les frais à l''avance.', '{}'::jsonb, '{"answer":0,"justification":"n''ont plus à avancer les frais chez le psychologue"}'::jsonb, null),
  (8, 'qcm', 'Quelle limite les spécialistes voient-ils dans les nouvelles aides ?', '{"options":["Elles ne règlent pas le manque de soignants.","Elles ne concernent que les étudiants.","Elles coûtent trop cher à la Sécurité sociale."]}'::jsonb, '{"answer":0}'::jsonb, '« elles ne remplacent pas un vrai plan pour former et recruter des soignants ».')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo22mvemxyoo02d' and q.ord = v.ord;
